svg.script:
{
  "metadata": {
    "title": "Infrastructure Architecture",
    "projectName": "Food Delivery System",
    "description": "Complete infrastructure architecture components and layers",
    "version": "1.0",
    "created": "2024-01-01T00:00:00Z",
    "mode": "light"
  },
  "config": {
    "layout": {"canvasWidth": 1920, "canvasHeight": 1080},
    "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#E5E5E5", "strokeColor": "#1A1A1A", "cornerRadius": 8, "strokeWidth": 1.5}
  },
  "data": {
    "layers": [
      {"id": "compute", "name": "Compute", "description": "Servers, VMs, Containers", "x": 200, "y": 300, "width": 240, "height": 140},
      {"id": "storage", "name": "Storage", "description": "Databases, Caches", "x": 560, "y": 300, "width": 240, "height": 140},
      {"id": "network", "name": "Network", "description": "Load Balancers, VPN", "x": 920, "y": 300, "width": 240, "height": 140},
      {"id": "security", "name": "Security", "description": "Firewalls, IAM", "x": 1280, "y": 300, "width": 240, "height": 140}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#infrastructure-architecture-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[Infrastructure Architecture Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[Infrastructure Architecture] Invalid JSON:', e.message);
  }
})();
